query getData($limit: Int!) {
  custom_fonts_connection(first: $limit, where: {}, order_by: {id: desc}) {
    edges {
      cursor
      node {
        id
        name
        original_name
        url
        master
        updated_at
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}
